// Tesco "All Departments" taxonomy (GraphQL batch response). Generated by `npm run types:taxonomy`
// from research/fixtures/categories.json; the file is an array of TescoTaxonomyResponse (one per batched query).

export interface TescoTaxonomyResponse {
    data:   Data;
    status: number;
}

export interface Data {
    // 17 super-departments -> 227 departments -> 1629 aisles (sample of 2026-11-21).
    taxonomy: Taxonomy[];
}

export interface Taxonomy {
    // "b;" + base64(encodeURIComponent("Super|Department|Aisle")), e.g. "Groceries & Essentials|Frozen Food|Ice Cream & Lollies".
    id:         string;
    // Display text: "Frozen Food".
    name:       string;
    // Tree level: "superDepartment" | "department" | "aisle".
    label:      string;
    // "essearch" for every node in the sample.
    source:     string;
    // "CATEGORY" (51 nodes, have a landing page) or "NONE".
    pageType:   null | string;
    // Absent on aisles (leaf level). No URLs anywhere: browse links are slugs of the names.
    children?:  Taxonomy[];
    __typename: string;
}
